-- 0229 — Academy, niveau 3 « Analyse technique » réécrit (2026-11-14).
--
-- Les cinq leçons précédentes étaient des gabarits générés, sans quiz, dont un
-- « Cas réel (Document MAF Carrefour) » sans rapport avec la BRVM. Sept leçons
-- au format du niveau 1 : nouvelles leçons 1 « Lire un graphique de cours » et
-- 5 « Le MACD » ; indicateurs réels via la vue donnees_reelles « technique »
-- (moyennes 20/50, RSI 14 sur les clôtures) ; mesure WestBourse 2008-2023 citée.
-- Source : frontend/lib/academy/contenus/niveau3/*.json (testés).
-- Sauvegarde : docs/academy/sauvegardes/2026-11-14-academy-niveau-3-technique.json
-- À appliquer APRÈS le déploiement de la vue « technique ».
-- Progression remappée (0→1, 1→2, 2→3, 3→5, 4→6) ; aucun élève au 2026-11-14.
-- refonte_majeure_le n'est PAS modifiée (elle pilote des droits d'accès).

do $do$
declare
  v_id uuid;
begin
  select id into v_id from public.academy_courses
   where slug = 'academy-niveau-3-technique'
     and jsonb_array_length(content->'lessons') = 5;
  if v_id is null then
    raise notice '0229 : cours déjà réécrit (ou introuvable), rien à faire';
    return;
  end if;

  -- Progression indexée par position : chaque ancienne leçon garde son élève.
  update public.academy_progress
     set lesson_idx = case lesson_idx when 0 then 1 when 1 then 2 when 2 then 3 when 3 then 5 when 4 then 6 else lesson_idx end
   where course_id = v_id;

  update public.academy_courses
     set content = jsonb_set(jsonb_set(content, '{lessons}', $wb$[{"titre": "Leçon 1 — Lire un graphique de cours", "module": "Module 1 — Graphiques et tendances", "categorie": "technical", "duree_min": 10, "sous_titre": "Tendance, supports, résistances et volume : les quatre choses à repérer avant tout indicateur.", "resume": "L’analyse technique étudie le cours et les volumes pour décrire le comportement du marché. Avant tout indicateur, il faut savoir lire un graphique : identifier une tendance, repérer les niveaux où le cours a déjà rebondi, et vérifier si les mouvements sont portés par des échanges réels. Cette leçon pose ces bases, et leurs limites à la BRVM.", "sections": [{"type": "definition", "titre": "Quatre notions de base", "contenu": "Un graphique de cours montre l’histoire des prix. Il se lit avant de se calculer.", "points": [{"titre": "La tendance", "detail": "Haussière si les sommets et les creux sont de plus en plus hauts ; baissière dans le cas inverse ; sans tendance sinon.", "verifier": "Les trois derniers creux et sommets."}, {"titre": "Le support", "detail": "Une zone de prix où le cours a cessé de baisser plusieurs fois : des acheteurs y sont apparus."}, {"titre": "La résistance", "detail": "Une zone où le cours a cessé de monter plusieurs fois : des vendeurs y sont apparus."}, {"titre": "Le volume", "detail": "Le nombre de titres échangés. Un mouvement sans volume est fragile.", "verifier": "Le volume du jour comparé à sa moyenne."}]}, {"type": "importance", "titre": "Les trois échelles de temps", "contenu": "Une même action peut monter sur un mois et baisser sur un an. Toujours préciser l’horizon.", "tableau": {"colonnes": ["Horizon", "Graphique utile", "Question"], "lignes": [["Court terme", "Quelques semaines, cours quotidien", "Le mouvement récent est-il confirmé par le volume ?"], ["Moyen terme", "Quelques mois", "La tendance est-elle intacte ?"], ["Long terme", "Plusieurs années", "Où se situe le cours dans son histoire ?"]], "note": "À la BRVM, le court terme est le plus bruité : peu d’échanges suffisent à déplacer un cours."}}, {"type": "piege", "titre": "Les limites propres à la BRVM", "contenu": "L’analyse technique a été développée sur des marchés très liquides. La BRVM ne l’est pas toujours.", "points": [{"titre": "Des cours qui ne bougent pas", "detail": "Une valeur peut rester plusieurs séances sans échange : son cours reste figé, sans information.", "verifier": "Le volume des dernières séances."}, {"titre": "Une variation encadrée", "detail": "La BRVM limite la variation d’un cours en une séance : un mouvement fort peut s’étaler sur plusieurs jours.", "verifier": "Les règles de cotation publiées par la BRVM."}, {"titre": "Une suspension", "detail": "Une valeur suspendue garde son dernier cours affiché : ce n’est pas un prix auquel on peut traiter.", "verifier": "La mention « suspendue » sur la fiche."}]}, {"type": "cas", "titre": "Sur la BRVM : une lecture du jour", "reel": true, "contenu": "Le cours de quatre valeurs, comparé à ses moyennes sur 20 et 50 séances, et son RSI. Tout est recalculé à l’ouverture de la leçon sur les clôtures réelles. C’est une description, pas un conseil.", "donnees_reelles": {"vue": "technique", "codes": ["SNTS", "SGBC", "ORAC", "PALC"]}}, {"type": "importance", "titre": "Ce que nous avons mesuré sur la BRVM", "contenu": "WestBourse a rejoué son score technique sur 2008-2023 : 109 634 séances que la formule n’avait jamais vues. Résultat : les titres les plus mal notés, souvent après une forte baisse, ont en moyenne fait mieux que le marché dans les semaines suivantes. Les mieux notés, non.\nSur un marché peu liquide, les excès ont plutôt tendance à se corriger. C’est une moyenne sur seize ans, pas une règle pour la prochaine séance.", "stats": [{"label": "Séances rejouées", "valeur": "109 634", "detail": "2008-2023, hors échantillon de construction"}, {"label": "Scores les plus bas, 20 séances après", "valeur": "+8,4 % face au marché", "detail": "Moyenne, écart statistiquement établi"}, {"label": "Scores les plus hauts, 20 séances après", "valeur": "−1,5 % face au marché", "detail": "Moyenne, écart non établi"}]}, {"type": "retenir", "titre": "L’essentiel", "contenu": "Lire avant de calculer.", "points": [{"titre": "Une tendance se lit aux sommets et aux creux successifs"}, {"titre": "Supports et résistances sont des zones, pas des prix exacts"}, {"titre": "Un mouvement sans volume est fragile, surtout à la BRVM"}, {"titre": "Un cours figé ou suspendu ne dit rien du prix réel"}]}], "quiz": [{"question": "Les sommets et les creux d’un cours sont de plus en plus hauts. Quelle est la tendance ?", "options": ["Baissière", "Haussière", "Sans tendance", "Impossible à dire"], "correct": 1, "explication": "Des sommets et des creux de plus en plus hauts définissent une tendance haussière."}, {"question": "Qu’est-ce qu’un support ?", "options": ["Le cours le plus haut de l’année", "Une zone où le cours a cessé de baisser plusieurs fois", "Le dividende", "Le volume moyen"], "correct": 1, "explication": "Un support est une zone de prix où des acheteurs sont apparus à plusieurs reprises."}, {"question": "Un cours monte de 5 % avec un volume très faible. Comment lire ce mouvement ?", "options": ["Comme très solide", "Comme fragile : peu d’échanges l’ont produit", "Comme une garantie de hausse", "Comme une erreur"], "correct": 1, "explication": "Sans volume, un mouvement peut venir de quelques ordres isolés."}, {"question": "Une valeur n’a pas été échangée depuis dix séances. Que vaut son cours affiché ?", "options": ["Le prix exact du marché", "Le dernier prix échangé, qui ne dit rien du prix actuel", "Zéro", "La moyenne du secteur"], "correct": 1, "explication": "Sans échange, le cours reste figé : ce n’est pas une information nouvelle."}, {"question": "D’après la mesure WestBourse sur 2008-2023, qu’ont fait en moyenne les titres les plus mal notés ?", "options": ["Ils ont continué à baisser", "Ils ont fait mieux que le marché dans les semaines suivantes", "Ils ont été radiés", "Rien de mesurable"], "correct": 1, "explication": "Sur seize ans, les excès à la baisse ont plutôt été suivis d’un rattrapage relatif. C’est une moyenne, pas une règle."}], "liens": [{"label": "Les fiches valeur et leurs graphiques", "href": "/actions"}, {"label": "Le scanner technique", "href": "/scanner"}, {"label": "Notre méthodologie des signaux", "href": "/methodologie"}], "avertissement": "Ceci n’est pas un conseil en investissement. Un indicateur technique décrit le passé des cours ; il ne prédit pas l’avenir. Investir en actions comporte un risque de perte en capital.", "charts": [], "qcm": {"question": "Les sommets et les creux d’un cours sont de plus en plus hauts. Quelle est la tendance ?", "options": ["Baissière", "Haussière", "Sans tendance", "Impossible à dire"], "correct": 1, "explication": "Des sommets et des creux de plus en plus hauts définissent une tendance haussière."}}, {"titre": "Leçon 2 — Les chandeliers japonais", "module": "Module 1 — Graphiques et tendances", "categorie": "technical", "duree_min": 9, "sous_titre": "Ouverture, plus haut, plus bas, clôture : ce qu’une bougie raconte d’une séance, et ce qu’elle ne raconte pas.", "resume": "Un chandelier résume une séance en quatre prix. Sa couleur dit si le cours a fini plus haut ou plus bas qu’à l’ouverture ; ses mèches montrent les extrêmes atteints. Cette leçon apprend à lire une bougie et quelques configurations connues, avec une prudence particulière à la BRVM.", "sections": [{"type": "definition", "titre": "L’anatomie d’une bougie", "contenu": "Chaque bougie représente une période : une séance, une semaine.", "points": [{"titre": "Le corps", "detail": "L’écart entre l’ouverture et la clôture. Clair (ou vert) : clôture au-dessus de l’ouverture. Sombre (ou rouge) : en dessous."}, {"titre": "La mèche haute", "detail": "Le plus haut atteint pendant la période."}, {"titre": "La mèche basse", "detail": "Le plus bas atteint pendant la période."}, {"titre": "La taille", "detail": "Un grand corps traduit un mouvement net ; un petit corps, de l’hésitation."}]}, {"type": "importance", "titre": "Quatre configurations connues", "contenu": "Ces figures décrivent un comportement ; aucune n’est un signal fiable à elle seule.", "tableau": {"colonnes": ["Configuration", "À quoi elle ressemble", "Ce qu’elle suggère"], "lignes": [["Doji", "Ouverture et clôture presque égales", "Hésitation entre acheteurs et vendeurs"], ["Marteau", "Petit corps en haut, longue mèche basse", "Les vendeurs ont poussé, les acheteurs ont repris le dessus"], ["Étoile filante", "Petit corps en bas, longue mèche haute", "Les acheteurs ont poussé, les vendeurs ont repris le dessus"], ["Avalement", "Un corps qui englobe entièrement le précédent", "Un changement de rapport de force"]], "note": "Une configuration se confirme par la séance suivante et par le volume."}}, {"type": "piege", "titre": "Les chandeliers à la BRVM", "contenu": "Une bougie suppose une séance active, avec de nombreux échanges.", "points": [{"titre": "Une bougie sans échange", "detail": "Sans transaction, ouverture, plus haut, plus bas et clôture sont identiques : la bougie est plate et ne dit rien.", "verifier": "Le volume de la séance."}, {"titre": "Peu d’ordres, beaucoup de forme", "detail": "Avec quelques échanges, une longue mèche peut venir d’un seul ordre isolé.", "verifier": "Le nombre de titres échangés."}, {"titre": "Des données incomplètes", "detail": "Les sources publiques ne fournissent pas toujours le plus haut et le plus bas de chaque séance. WestBourse affiche alors des courbes de clôture plutôt que des bougies inventées.", "verifier": "La mention de la source sous le graphique."}]}, {"type": "retenir", "titre": "L’essentiel", "contenu": "Une bougie raconte une séance ; elle ne prédit pas la suivante.", "points": [{"titre": "Le corps : ouverture et clôture ; les mèches : les extrêmes"}, {"titre": "Doji, marteau, étoile filante, avalement : des indices, pas des signaux"}, {"titre": "Toujours vérifier le volume"}, {"titre": "À la BRVM, une bougie sans échange ne dit rien"}]}], "quiz": [{"question": "Une bougie a un corps clair. Qu’est-ce que cela signifie ?", "options": ["La clôture est sous l’ouverture", "La clôture est au-dessus de l’ouverture", "Il n’y a pas eu d’échange", "Le cours a atteint un record"], "correct": 1, "explication": "Un corps clair (ou vert) indique une clôture supérieure à l’ouverture."}, {"question": "Que représente la mèche basse ?", "options": ["La clôture", "Le plus bas atteint pendant la période", "Le dividende", "Le volume"], "correct": 1, "explication": "La mèche basse descend jusqu’au plus bas de la période."}, {"question": "Un doji traduit plutôt :", "options": ["Une forte hausse", "Une hésitation entre acheteurs et vendeurs", "Une suspension", "Un dividende"], "correct": 1, "explication": "Ouverture et clôture presque égales : aucun camp ne l’a emporté."}, {"question": "Une valeur n’a eu aucun échange dans la séance. À quoi ressemble sa bougie ?", "options": ["À un marteau", "À un trait plat, sans information", "À un avalement", "À une étoile filante"], "correct": 1, "explication": "Sans transaction, les quatre prix sont identiques."}, {"question": "Comment confirmer une configuration de chandeliers ?", "options": ["Par la couleur du logo", "Par la séance suivante et par le volume", "Par le PER", "Elle n’a pas besoin de confirmation"], "correct": 1, "explication": "Une configuration isolée est un indice ; la suite des cours et le volume la confirment ou non."}], "liens": [{"label": "Les fiches valeur et leurs graphiques", "href": "/actions"}, {"label": "Le scanner technique", "href": "/scanner"}, {"label": "La liquidité de chaque valeur", "href": "/liquidite"}], "avertissement": "Ceci n’est pas un conseil en investissement. Un indicateur technique décrit le passé des cours ; il ne prédit pas l’avenir. Investir en actions comporte un risque de perte en capital.", "charts": [], "qcm": {"question": "Une bougie a un corps clair. Qu’est-ce que cela signifie ?", "options": ["La clôture est sous l’ouverture", "La clôture est au-dessus de l’ouverture", "Il n’y a pas eu d’échange", "Le cours a atteint un record"], "correct": 1, "explication": "Un corps clair (ou vert) indique une clôture supérieure à l’ouverture."}}, {"titre": "Leçon 3 — Les moyennes mobiles", "module": "Module 2 — Indicateurs", "categorie": "technical", "duree_min": 10, "sous_titre": "Lisser le bruit des séances pour voir la tendance : moyenne courte, moyenne longue, et leurs croisements.", "resume": "Une moyenne mobile calcule la moyenne des derniers cours de clôture, recalculée à chaque séance. Elle lisse les variations et révèle la tendance. Cette leçon explique le calcul, la lecture du cours face à ses moyennes, et pourquoi les croisements arrivent toujours en retard.", "sections": [{"type": "definition", "titre": "Le calcul", "contenu": "Exemple pédagogique sur cinq séances.", "formules": [{"nom": "Moyenne mobile simple sur N séances", "expression": "(Somme des N dernières clôtures) ÷ N", "exemple": "(100 + 102 + 101 + 105 + 107) ÷ 5 = 103"}, {"nom": "Écart à la moyenne", "expression": "(Cours − Moyenne) ÷ Moyenne", "exemple": "(107 − 103) ÷ 103 ≈ +3,9 %"}]}, {"type": "importance", "titre": "Moyenne courte et moyenne longue", "contenu": "Une moyenne courte (20 séances, environ un mois) suit le cours de près. Une moyenne longue (50 séances ou plus) décrit la tendance de fond.\nLe graphique de la leçon montre, avec des valeurs d’exemple, un cours qui passe au-dessus de sa moyenne.", "stats": [{"label": "Cours au-dessus des deux moyennes", "valeur": "Tendance haussière", "detail": "Description de la situation, pas une prévision"}, {"label": "Cours sous les deux moyennes", "valeur": "Tendance baissière", "detail": "Idem"}, {"label": "Cours entre les deux", "valeur": "Hésitation", "detail": "Tendances courte et longue divergentes"}]}, {"type": "cas", "titre": "Sur la BRVM : le cours face à ses moyennes", "reel": true, "contenu": "Les moyennes sur 20 et 50 séances de cinq valeurs, calculées à l’ouverture de la leçon sur les clôtures réelles.", "donnees_reelles": {"vue": "technique", "codes": ["SNTS", "ORAC", "SGBC", "ETIT", "SIBC"]}}, {"type": "piege", "titre": "Le retard, défaut inévitable", "contenu": "Une moyenne mobile regarde en arrière : elle confirme une tendance quand celle-ci est déjà installée.", "points": [{"titre": "Les croisements arrivent tard", "detail": "Quand la moyenne courte croise la longue, une bonne partie du mouvement a souvent eu lieu.", "verifier": "L’écart du cours à sa moyenne au moment du croisement."}, {"titre": "Les faux signaux en marché sans tendance", "detail": "Quand le cours oscille, les moyennes se croisent sans cesse.", "verifier": "La pente de la moyenne longue."}, {"titre": "Des séances sans échange", "detail": "Une moyenne calculée sur des cours figés paraît stable sans l’être.", "verifier": "Le nombre de séances réellement échangées."}]}, {"type": "retenir", "titre": "L’essentiel", "contenu": "Une moyenne mobile décrit, elle ne prévoit pas.", "points": [{"titre": "Moyenne mobile = moyenne des N dernières clôtures"}, {"titre": "Courte pour le mouvement récent, longue pour la tendance de fond"}, {"titre": "Le cours face à ses deux moyennes décrit la tendance"}, {"titre": "Les croisements arrivent en retard et se trompent sans tendance"}]}], "charts": [{"type": "line", "titre": "Un cours qui repasse au-dessus de sa moyenne (exemple)", "labels": ["S1", "S2", "S3", "S4", "S5", "S6", "S7", "S8", "S9", "S10"], "valeurs": [100, 98, 97, 99, 102, 105, 107, 106, 109, 112], "unite": "FCFA", "note": "Valeurs d’exemple. Moyenne sur 5 séances : 99,2 à la séance 5, 105,8 à la séance 9, 107,8 à la séance 10. Le cours passe au-dessus de sa moyenne à partir de la séance 5 et y reste : la moyenne confirme la hausse, avec retard.", "reel": false}], "quiz": [{"question": "Quelle est la moyenne mobile sur 4 séances des clôtures 200, 210, 190 et 220 ?", "options": ["200", "205", "210", "820"], "correct": 1, "explication": "(200 + 210 + 190 + 220) ÷ 4 = 205."}, {"question": "Le cours est au-dessus de sa moyenne sur 20 séances et de sa moyenne sur 50 séances. Comment le décrire ?", "options": ["Tendance baissière", "Tendance haussière", "Valeur suspendue", "Achat garanti"], "correct": 1, "explication": "Un cours au-dessus de ses deux moyennes décrit une tendance haussière, sans rien garantir."}, {"question": "Pourquoi un croisement de moyennes arrive-t-il en retard ?", "options": ["Parce que les moyennes regardent les cours passés", "Parce que la BRVM publie tard", "Parce que le volume est faible", "Il n’arrive jamais en retard"], "correct": 0, "explication": "Une moyenne se calcule sur des cours passés : elle réagit après le mouvement."}, {"question": "Dans un marché sans tendance, les croisements de moyennes :", "options": ["Sont très fiables", "Se multiplient et donnent beaucoup de faux signaux", "Disparaissent", "Annoncent un dividende"], "correct": 1, "explication": "Quand le cours oscille, les moyennes se croisent souvent sans tendance réelle."}, {"question": "Un cours vaut 110 et sa moyenne 100. Quel est son écart à la moyenne ?", "options": ["+1 %", "+10 %", "+110 %", "−10 %"], "correct": 1, "explication": "(110 − 100) ÷ 100 = +10 %."}], "liens": [{"label": "Les fiches valeur et leurs graphiques", "href": "/actions"}, {"label": "Le scanner technique", "href": "/scanner"}, {"label": "Notre méthodologie des signaux", "href": "/methodologie"}], "avertissement": "Ceci n’est pas un conseil en investissement. Un indicateur technique décrit le passé des cours ; il ne prédit pas l’avenir. Investir en actions comporte un risque de perte en capital.", "qcm": {"question": "Quelle est la moyenne mobile sur 4 séances des clôtures 200, 210, 190 et 220 ?", "options": ["200", "205", "210", "820"], "correct": 1, "explication": "(200 + 210 + 190 + 220) ÷ 4 = 205."}}, {"titre": "Leçon 4 — Le RSI : mesurer les excès de marché", "module": "Module 2 — Indicateurs", "categorie": "technical", "duree_min": 10, "sous_titre": "Un indicateur borné de 0 à 100 qui compare les hausses et les baisses récentes, et ce qu’il vaut sur un marché peu liquide.", "resume": "Le RSI (relative strength index) compare l’ampleur des hausses et des baisses sur les dernières séances, en général 14. Au-dessus de 70, on parle de surachat ; sous 30, de survente. Cette leçon explique son calcul, sa lecture et ce que les mesures faites sur la BRVM disent de ces excès.", "sections": [{"type": "definition", "titre": "Le calcul", "contenu": "Le RSI ramène le rapport entre hausses et baisses moyennes sur une échelle de 0 à 100. Exemple pédagogique.", "formules": [{"nom": "Force relative (RS)", "expression": "Hausse moyenne ÷ Baisse moyenne, sur 14 séances", "exemple": "2 ÷ 1 = 2"}, {"nom": "RSI", "expression": "100 − 100 ÷ (1 + RS)", "exemple": "100 − 100 ÷ 3 ≈ 66,7"}]}, {"type": "importance", "titre": "Les trois zones", "contenu": "Les seuils de 70 et 30 sont des conventions, pas des lois.", "stats": [{"label": "RSI supérieur à 70", "valeur": "Surachat", "detail": "Les hausses récentes dominent nettement"}, {"label": "RSI entre 30 et 70", "valeur": "Zone neutre", "detail": "Pas d’excès marqué"}, {"label": "RSI inférieur à 30", "valeur": "Survente", "detail": "Les baisses récentes dominent nettement"}]}, {"type": "cas", "titre": "Sur la BRVM : le RSI du jour", "reel": true, "contenu": "Le RSI sur 14 séances de cinq valeurs, recalculé à l’ouverture de la leçon. Un RSI en zone extrême décrit un mouvement récent ; il ne dit pas quand il s’arrêtera.", "donnees_reelles": {"vue": "technique", "codes": ["SNTS", "BOAC", "NTLC", "SDCC", "TTLC"]}}, {"type": "importance", "titre": "Ce que nous avons mesuré sur la BRVM", "contenu": "WestBourse a rejoué son score technique sur 2008-2023 : 109 634 séances que la formule n’avait jamais vues. Résultat : les titres les plus mal notés, souvent après une forte baisse, ont en moyenne fait mieux que le marché dans les semaines suivantes. Les mieux notés, non.\nSur un marché peu liquide, les excès ont plutôt tendance à se corriger. C’est une moyenne sur seize ans, pas une règle pour la prochaine séance.", "stats": [{"label": "Séances rejouées", "valeur": "109 634", "detail": "2008-2023, hors échantillon de construction"}, {"label": "Scores les plus bas, 20 séances après", "valeur": "+8,4 % face au marché", "detail": "Moyenne, écart statistiquement établi"}, {"label": "Scores les plus hauts, 20 séances après", "valeur": "−1,5 % face au marché", "detail": "Moyenne, écart non établi"}]}, {"type": "piege", "titre": "Les mauvaises lectures du RSI", "contenu": "Le RSI est populaire, et souvent mal utilisé.", "points": [{"titre": "« Surachat » ne veut pas dire « vendre »", "detail": "Dans une forte tendance, le RSI peut rester au-dessus de 70 longtemps.", "verifier": "La tendance de fond, sur la moyenne longue."}, {"titre": "Peu d’échanges, RSI extrême", "detail": "Sur une valeur peu liquide, deux ou trois séances suffisent à pousser le RSI vers un extrême.", "verifier": "Les volumes des séances qui ont fait bouger le RSI."}, {"titre": "Un indicateur parmi d’autres", "detail": "Le RSI ne dit rien de la société : ni de ses comptes, ni de son dividende.", "verifier": "Les fondamentaux, avant toute décision."}]}, {"type": "retenir", "titre": "L’essentiel", "contenu": "Le RSI mesure un excès récent, pas une valeur.", "points": [{"titre": "RSI = 100 − 100 ÷ (1 + RS), en général sur 14 séances"}, {"titre": "Au-dessus de 70 : surachat ; sous 30 : survente"}, {"titre": "Une zone extrême peut durer dans une tendance forte"}, {"titre": "À la BRVM, les excès ont plutôt eu tendance à se corriger en moyenne"}]}], "charts": [{"type": "line", "titre": "Un RSI qui traverse ses zones (exemple)", "labels": ["S1", "S2", "S3", "S4", "S5", "S6", "S7", "S8", "S9", "S10"], "valeurs": [48, 55, 63, 72, 76, 71, 60, 44, 29, 35], "unite": "RSI", "note": "Valeurs d’exemple. Le RSI passe en surachat (au-dessus de 70) aux séances 4 à 6, revient en zone neutre, puis touche la survente (sous 30) à la séance 9. Ces passages décrivent l’intensité du mouvement ; ils ne datent pas le retournement.", "reel": false}], "quiz": [{"question": "La hausse moyenne vaut 3 et la baisse moyenne 1. Quel est le RSI ?", "options": ["25", "50", "75", "300"], "correct": 2, "explication": "RS = 3 ; RSI = 100 − 100 ÷ (1 + 3) = 75."}, {"question": "Un RSI de 25 se situe dans quelle zone ?", "options": ["Surachat", "Neutre", "Survente", "Hors échelle"], "correct": 2, "explication": "Sous 30, on parle de survente."}, {"question": "Un RSI reste au-dessus de 70 pendant des semaines. Est-ce possible ?", "options": ["Non, c’est impossible", "Oui, dans une forte tendance haussière", "Seulement pour les obligations", "Seulement les jours fériés"], "correct": 1, "explication": "Une tendance forte peut maintenir le RSI en zone de surachat."}, {"question": "Pourquoi le RSI d’une valeur peu liquide est-il à lire avec prudence ?", "options": ["Il ne se calcule pas", "Quelques séances avec peu d’échanges suffisent à le pousser vers un extrême", "Il vaut toujours 50", "Il est interdit"], "correct": 1, "explication": "Avec peu d’échanges, quelques ordres font bouger le cours, et donc le RSI."}, {"question": "Que dit le RSI sur les comptes d’une société ?", "options": ["Tout", "Rien : il ne mesure que les mouvements de cours", "Son bénéfice", "Son dividende"], "correct": 1, "explication": "Le RSI est calculé sur les cours seulement."}], "liens": [{"label": "Les fiches valeur et leurs graphiques", "href": "/actions"}, {"label": "Le scanner technique", "href": "/scanner"}, {"label": "Notre méthodologie des signaux", "href": "/methodologie"}], "avertissement": "Ceci n’est pas un conseil en investissement. Un indicateur technique décrit le passé des cours ; il ne prédit pas l’avenir. Investir en actions comporte un risque de perte en capital.", "qcm": {"question": "La hausse moyenne vaut 3 et la baisse moyenne 1. Quel est le RSI ?", "options": ["25", "50", "75", "300"], "correct": 2, "explication": "RS = 3 ; RSI = 100 − 100 ÷ (1 + 3) = 75."}}, {"titre": "Leçon 5 — Le MACD : l’élan d’une tendance", "module": "Module 2 — Indicateurs", "categorie": "technical", "duree_min": 9, "sous_titre": "Deux moyennes exponentielles, leur écart, et le signal qui en découle : un indicateur de dynamique.", "resume": "Le MACD mesure l’écart entre une moyenne exponentielle courte et une longue. Quand l’écart grandit, la tendance accélère ; quand il se resserre, elle ralentit. Cette leçon explique ses trois composantes et ce qu’on peut, ou non, en tirer.", "sections": [{"type": "definition", "titre": "Trois composantes", "contenu": "Les paramètres usuels sont 12, 26 et 9 séances.", "formules": [{"nom": "Ligne MACD", "expression": "Moyenne exponentielle 12 − Moyenne exponentielle 26", "exemple": "105 − 102 = +3 : la tendance courte est au-dessus de la longue"}, {"nom": "Ligne de signal", "expression": "Moyenne exponentielle sur 9 séances de la ligne MACD", "exemple": "Elle lisse la ligne MACD"}, {"nom": "Histogramme", "expression": "Ligne MACD − Ligne de signal", "exemple": "Positif et croissant : l’élan haussier se renforce"}]}, {"type": "importance", "titre": "Moyenne exponentielle : pourquoi ?", "contenu": "Une moyenne exponentielle donne plus de poids aux séances récentes qu’une moyenne simple. Elle réagit plus vite, au prix de plus de bruit.\nLe MACD n’est pas borné comme le RSI : sa valeur dépend du niveau du cours, et ne se compare pas d’une action à l’autre."}, {"type": "cas", "titre": "Lire l’histogramme", "contenu": "Exemple pédagogique : l’histogramme décrit l’accélération ou le ralentissement de la tendance.", "tableau": {"colonnes": ["Histogramme", "Lecture"], "lignes": [["Positif et croissant", "La tendance haussière s’accélère"], ["Positif et décroissant", "La hausse ralentit"], ["Négatif et décroissant", "La tendance baissière s’accélère"], ["Négatif et croissant", "La baisse ralentit"]], "note": "Le passage de l’histogramme d’un signe à l’autre correspond au croisement des lignes MACD et signal."}}, {"type": "piege", "titre": "Ce que le MACD ne fait pas", "contenu": "Le MACD hérite des défauts des moyennes mobiles.", "points": [{"titre": "Il est en retard", "detail": "Construit sur des moyennes, il confirme plus qu’il n’anticipe.", "verifier": "Le moment du croisement par rapport au mouvement du cours."}, {"titre": "Il ne se compare pas entre actions", "detail": "Un MACD de +50 sur une action à 30 000 FCFA n’a rien à voir avec +50 sur une action à 500 FCFA.", "verifier": "L’écart rapporté au cours."}, {"titre": "Il trompe sans tendance", "detail": "Dans un marché qui oscille, les croisements se multiplient.", "verifier": "La pente des moyennes."}]}, {"type": "retenir", "titre": "L’essentiel", "contenu": "Le MACD mesure un élan, pas une destination.", "points": [{"titre": "MACD = moyenne exponentielle 12 − moyenne exponentielle 26"}, {"titre": "Signal = moyenne exponentielle 9 du MACD ; histogramme = leur écart"}, {"titre": "L’histogramme décrit l’accélération ou le ralentissement"}, {"titre": "Il ne se compare pas d’une action à l’autre"}]}], "charts": [{"type": "bar", "titre": "Un histogramme de MACD (exemple)", "labels": ["S1", "S2", "S3", "S4", "S5", "S6", "S7", "S8"], "valeurs": [-3, -2, -0.5, 1, 2.5, 3, 2, 0.5], "unite": "", "note": "Valeurs d’exemple. Négatif et croissant (S1 à S3) : la baisse ralentit. Il devient positif à S4 (croisement), grandit jusqu’à S6 (la hausse accélère), puis diminue (la hausse ralentit). Aucune de ces phases ne dit combien de temps durera la suivante.", "reel": false}], "quiz": [{"question": "La moyenne exponentielle 12 vaut 250 et la 26 vaut 240. Que vaut la ligne MACD ?", "options": ["−10", "+10", "490", "250"], "correct": 1, "explication": "250 − 240 = +10."}, {"question": "L’histogramme est positif et croissant. Que décrit-il ?", "options": ["Une baisse qui accélère", "Une hausse qui accélère", "Une suspension", "Un dividende"], "correct": 1, "explication": "Positif et croissant : la tendance haussière s’accélère."}, {"question": "Pourquoi ne pas comparer le MACD de deux actions différentes ?", "options": ["Il est confidentiel", "Sa valeur dépend du niveau du cours", "Il est toujours égal", "Il est borné de 0 à 100"], "correct": 1, "explication": "Le MACD s’exprime en points de cours : il dépend du prix de l’action."}, {"question": "Qu’est-ce qui distingue une moyenne exponentielle d’une moyenne simple ?", "options": ["Elle ignore les séances récentes", "Elle donne plus de poids aux séances récentes", "Elle ne se calcule que sur les dividendes", "Rien"], "correct": 1, "explication": "Les séances récentes pèsent plus : la moyenne réagit plus vite."}, {"question": "Quels sont les paramètres usuels du MACD ?", "options": ["5, 10, 15", "12, 26, 9", "14, 70, 30", "20, 50, 200"], "correct": 1, "explication": "12 et 26 pour les moyennes, 9 pour la ligne de signal."}], "liens": [{"label": "Les fiches valeur et leurs graphiques", "href": "/actions"}, {"label": "Le scanner technique", "href": "/scanner"}, {"label": "Notre méthodologie des signaux", "href": "/methodologie"}], "avertissement": "Ceci n’est pas un conseil en investissement. Un indicateur technique décrit le passé des cours ; il ne prédit pas l’avenir. Investir en actions comporte un risque de perte en capital.", "qcm": {"question": "La moyenne exponentielle 12 vaut 250 et la 26 vaut 240. Que vaut la ligne MACD ?", "options": ["−10", "+10", "490", "250"], "correct": 1, "explication": "250 − 240 = +10."}}, {"titre": "Leçon 6 — Les figures chartistes classiques", "module": "Module 3 — Figures et gestion du risque", "categorie": "technical", "duree_min": 10, "sous_titre": "Double creux, tête-épaules, triangles : des formes que le cours dessine, et la discipline qu’il faut pour ne pas en voir partout.", "resume": "Les figures chartistes sont des formes récurrentes du cours, associées à une continuation ou à un retournement de tendance. Cette leçon présente les principales, la façon de les confirmer, et le risque de les voir là où il n’y a que du bruit.", "sections": [{"type": "definition", "titre": "Retournement ou continuation", "contenu": "Les figures se classent selon ce qu’elles suggèrent.", "tableau": {"colonnes": ["Figure", "Famille", "Description", "Confirmation"], "lignes": [["Double creux", "Retournement haussier", "Deux creux au même niveau, séparés d’un sommet", "Cassure du sommet intermédiaire"], ["Double sommet", "Retournement baissier", "Deux sommets au même niveau, séparés d’un creux", "Cassure du creux intermédiaire"], ["Tête-épaules", "Retournement baissier", "Trois sommets, celui du milieu le plus haut", "Cassure de la ligne de cou"], ["Triangle", "Continuation, le plus souvent", "Des oscillations qui se resserrent", "Sortie du triangle avec du volume"], ["Canal", "Continuation", "Le cours évolue entre deux droites parallèles", "Rebonds répétés sur les bornes"]], "note": "Une figure n’existe vraiment qu’une fois confirmée ; avant, ce n’est qu’une hypothèse."}}, {"type": "importance", "titre": "La méthode : attendre la cassure", "contenu": "La règle commune à toutes les figures : ne rien conclure avant la confirmation.", "etapes": [{"titre": "Repérer la forme", "detail": "Sur un horizon suffisant : quelques semaines au moins."}, {"titre": "Identifier le niveau clé", "detail": "Le sommet intermédiaire, la ligne de cou, la borne du triangle."}, {"titre": "Attendre la cassure", "detail": "Une clôture au-delà du niveau clé, pas une simple mèche.", "cle": true}, {"titre": "Vérifier le volume", "detail": "Une cassure sans volume est suspecte, surtout à la BRVM."}, {"titre": "Fixer d’avance où l’on s’est trompé", "detail": "Le niveau qui invaliderait la figure : c’est la leçon suivante."}], "etapes_style": "frise"}, {"type": "piege", "titre": "Voir des figures partout", "contenu": "L’œil humain trouve des formes même dans le hasard.", "points": [{"titre": "Conclure avant la cassure", "detail": "Une figure non confirmée échoue souvent.", "verifier": "La clôture au-delà du niveau clé."}, {"titre": "Choisir l’horizon qui arrange", "detail": "En changeant d’échelle, on trouve presque toujours une figure.", "verifier": "La même lecture sur un autre horizon."}, {"titre": "Ignorer la liquidité", "detail": "Sur une valeur peu échangée, une « cassure » peut venir d’un seul ordre.", "verifier": "Le volume du jour de cassure."}]}, {"type": "retenir", "titre": "L’essentiel", "contenu": "Une figure est une hypothèse jusqu’à sa confirmation.", "points": [{"titre": "Double creux, double sommet, tête-épaules : des retournements"}, {"titre": "Triangles et canaux : plutôt des continuations"}, {"titre": "Attendre une clôture au-delà du niveau clé, avec du volume"}, {"titre": "Savoir d’avance ce qui invaliderait la figure"}]}], "quiz": [{"question": "Une tête-épaules suggère plutôt :", "options": ["Une continuation haussière", "Un retournement baissier", "Un dividende", "Une suspension"], "correct": 1, "explication": "Trois sommets, celui du milieu le plus haut : figure de retournement baissier."}, {"question": "Quand une figure est-elle confirmée ?", "options": ["Dès qu’on la voit", "Quand le cours clôture au-delà du niveau clé, avec du volume", "Quand le RSI vaut 50", "Jamais"], "correct": 1, "explication": "La cassure du niveau clé, en clôture et avec du volume, confirme la figure."}, {"question": "Un double creux se confirme par :", "options": ["La cassure du creux le plus bas", "La cassure du sommet intermédiaire", "Une baisse du volume", "Un nouveau dividende"], "correct": 1, "explication": "Le double creux est confirmé quand le cours dépasse le sommet entre les deux creux."}, {"question": "Pourquoi une cassure sur une valeur peu liquide est-elle suspecte ?", "options": ["Elle est interdite", "Elle peut venir d’un seul ordre isolé", "Elle est toujours fiable", "Elle n’existe pas"], "correct": 1, "explication": "Avec peu d’échanges, un ordre isolé suffit à franchir un niveau."}, {"question": "Un triangle est le plus souvent une figure de :", "options": ["Retournement", "Continuation", "Liquidation", "Dividende"], "correct": 1, "explication": "Le triangle traduit le plus souvent une pause avant la reprise de la tendance."}], "liens": [{"label": "Les fiches valeur et leurs graphiques", "href": "/actions"}, {"label": "Le scanner technique", "href": "/scanner"}, {"label": "La liquidité de chaque valeur", "href": "/liquidite"}], "avertissement": "Ceci n’est pas un conseil en investissement. Un indicateur technique décrit le passé des cours ; il ne prédit pas l’avenir. Investir en actions comporte un risque de perte en capital.", "charts": [], "qcm": {"question": "Une tête-épaules suggère plutôt :", "options": ["Une continuation haussière", "Un retournement baissier", "Un dividende", "Une suspension"], "correct": 1, "explication": "Trois sommets, celui du milieu le plus haut : figure de retournement baissier."}}, {"titre": "Leçon 7 — Stop-loss, objectif et taille de position", "module": "Module 3 — Figures et gestion du risque", "categorie": "technical", "duree_min": 11, "sous_titre": "Décider avant d’acheter combien on accepte de perdre, et en déduire combien acheter.", "resume": "La gestion du risque compte davantage que le choix du point d’entrée. Elle consiste à fixer à l’avance le niveau où l’on reconnaît s’être trompé, à en déduire la taille de la position, et à comparer le gain visé au risque pris. Cette leçon donne les calculs et leurs limites sur un marché peu liquide.", "sections": [{"type": "definition", "titre": "Trois décisions à prendre avant l’achat", "contenu": "Elles s’écrivent avant de passer l’ordre, jamais après.", "points": [{"titre": "Le niveau d’invalidation (stop)", "detail": "Le prix auquel votre raisonnement est faux : sous un support, sous la ligne de cou."}, {"titre": "L’objectif", "detail": "Un niveau plausible de sortie : une résistance, un sommet précédent."}, {"titre": "La taille de la position", "detail": "Calculée pour qu’une sortie au stop ne coûte qu’une petite part du portefeuille."}]}, {"type": "importance", "titre": "Les calculs", "contenu": "Exemple pédagogique : portefeuille de 5 000 000 FCFA, risque accepté de 1 % par position.", "formules": [{"nom": "Risque maximal par position", "expression": "Portefeuille × % de risque accepté", "exemple": "5 000 000 × 1 % = 50 000 FCFA"}, {"nom": "Risque par action", "expression": "Prix d’achat − Stop", "exemple": "2 000 − 1 800 = 200 FCFA"}, {"nom": "Nombre d’actions", "expression": "Risque maximal ÷ Risque par action", "exemple": "50 000 ÷ 200 = 250 actions, soit 500 000 FCFA investis"}]}, {"type": "cas", "titre": "Le rapport gain sur risque", "contenu": "Exemple pédagogique : avec un stop à 1 800 et un objectif à 2 500 pour un achat à 2 000 FCFA.", "tableau": {"colonnes": ["Élément", "Calcul", "Résultat"], "lignes": [["Risque par action", "2 000 − 1 800", "200 FCFA"], ["Gain visé par action", "2 500 − 2 000", "500 FCFA"], ["Rapport gain sur risque", "500 ÷ 200", "2,5"], ["Taux de réussite nécessaire pour ne pas perdre", "1 ÷ (1 + 2,5)", "Environ 29 %"]], "note": "Avec un rapport de 2,5, il suffit d’avoir raison un peu moins d’une fois sur trois pour ne pas perdre, hors frais."}}, {"type": "piege", "titre": "Les limites à la BRVM", "contenu": "Un stop n’est pas une garantie de prix.", "points": [{"titre": "Le stop n’est pas automatique partout", "detail": "Selon les SGI, l’ordre stop n’existe pas toujours : il faut alors surveiller soi-même et passer l’ordre.", "verifier": "Les types d’ordres proposés par votre SGI."}, {"titre": "Le prix peut sauter le stop", "detail": "Sur une valeur peu liquide, le cours peut passer d’un coup sous votre niveau : la vente se fait plus bas.", "verifier": "La liquidité de la valeur avant d’acheter."}, {"titre": "Les frais", "detail": "Courtage à l’achat et à la vente réduisent le gain et augmentent la perte.", "verifier": "Le barème de votre SGI."}, {"titre": "Déplacer son stop vers le bas", "detail": "Le reculer pour « laisser une chance » transforme une petite perte en grande perte.", "verifier": "Votre règle écrite avant l’achat."}]}, {"type": "retenir", "titre": "L’essentiel", "contenu": "On ne contrôle pas le marché ; on contrôle ce qu’on risque.", "points": [{"titre": "Fixer le stop et l’objectif avant l’achat"}, {"titre": "Taille de position = risque accepté ÷ risque par action"}, {"titre": "Viser un rapport gain sur risque d’au moins 2"}, {"titre": "À la BRVM, le stop est une intention : la liquidité décide du prix réel"}]}], "quiz": [{"question": "Portefeuille de 2 000 000 FCFA, risque accepté de 2 % par position. Quel est le risque maximal ?", "options": ["4 000 FCFA", "40 000 FCFA", "400 000 FCFA", "20 000 FCFA"], "correct": 1, "explication": "2 000 000 × 2 % = 40 000 FCFA."}, {"question": "Achat à 3 000 FCFA, stop à 2 700 FCFA, risque maximal de 30 000 FCFA. Combien d’actions acheter ?", "options": ["10", "100", "300", "1 000"], "correct": 1, "explication": "Risque par action : 300 FCFA ; 30 000 ÷ 300 = 100 actions."}, {"question": "Stop à 900, achat à 1 000, objectif à 1 300. Quel est le rapport gain sur risque ?", "options": ["1", "2", "3", "13"], "correct": 2, "explication": "Gain visé 300, risque 100 : rapport de 3."}, {"question": "Pourquoi un stop ne garantit-il pas le prix de vente à la BRVM ?", "options": ["Il est interdit", "Sur une valeur peu liquide, le cours peut sauter le niveau du stop", "Les stops sont toujours exécutés au cours d’achat", "La BRVM rembourse la différence"], "correct": 1, "explication": "Sans contrepartie au niveau du stop, la vente se fait au prix suivant disponible."}, {"question": "Quelle est l’erreur la plus coûteuse avec un stop ?", "options": ["Le fixer avant d’acheter", "Le reculer vers le bas quand le cours s’en approche", "Calculer la taille de position", "Noter son raisonnement"], "correct": 1, "explication": "Reculer son stop transforme une perte contrôlée en perte non contrôlée."}], "liens": [{"label": "Le portefeuille virtuel", "href": "/premium/paper-trading"}, {"label": "Choisir sa SGI", "href": "/comparateur-sgi"}, {"label": "La liquidité de chaque valeur", "href": "/liquidite"}], "avertissement": "Ceci n’est pas un conseil en investissement. Un indicateur technique décrit le passé des cours ; il ne prédit pas l’avenir. Investir en actions comporte un risque de perte en capital.", "charts": [], "qcm": {"question": "Portefeuille de 2 000 000 FCFA, risque accepté de 2 % par position. Quel est le risque maximal ?", "options": ["4 000 FCFA", "40 000 FCFA", "400 000 FCFA", "20 000 FCFA"], "correct": 1, "explication": "2 000 000 × 2 % = 40 000 FCFA."}}]$wb$::jsonb), '{intro}', to_jsonb($wb$Niveau 3 — Analyse technique. Sept leçons pour lire un graphique, comprendre les chandeliers, les moyennes mobiles, le RSI et le MACD, reconnaître les figures chartistes et gérer son risque. Les indicateurs des valeurs citées sont recalculés sur les clôtures réelles à l’ouverture de chaque leçon ; les graphiques d’illustration sont des exemples annoncés comme tels.$wb$::text)),
         updated_at = now()
   where id = v_id;
end
